import{_ as e,o as i,c as d,ag as a}from"./chunks/framework.DaCm-iTo.js";const k=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":null}'),o={name:"guide/introduction.md"};function l(r,t,c,m,h,n){return i(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p>Emaki Series 是一组面向 Minecraft 1.21.8+ 的 RPG 插件模块。它不把所有玩法塞进一个插件，而是把公共能力放进 CoreLib，把属性、装备、强化、宝石、等级、技能、烹饪和图鉴拆成可组合模块。</p><p>如果你的服务器需要下面这些能力，按模块选择安装即可：</p><ul><li>装备应该有稳定 ID、名称、Lore、属性、套装和技能绑定。</li><li>属性系统需要支持物理、法术、投射物、暴击、防御、穿透、资源等数值。</li><li>装备成长需要锻造、强化、宝石、品质、材料、失败惩罚和展示刷新。</li><li>玩家成长需要多等级类型、经验来源、升级需求、排行榜、PDC 和 PlaceholderAPI 展示。</li><li>技能需要主动释放、被动触发、冷却、资源消耗、等级参数和外部技能引擎联动。</li><li>玩法系统需要世界工位、交互流程、输入材料、产物发放和状态持久化。</li><li>收集与目标引导需要原版成就页、节点触发器和完成奖励动作。</li><li>所有模块需要共享动作、GUI、物品来源、经济、PDC 和配置加载能力。</li></ul><p>后续文档会按模块说明配置目录、命令、权限、核心 YAML 字段和验证方式。</p><h2 id="技术基线" tabindex="-1">技术基线 <a class="header-anchor" href="#技术基线" aria-label="Permalink to &quot;技术基线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>当前基线</th></tr></thead><tbody><tr><td>服务端</td><td>Paper 1.21.8+（最低支持 1.21.8）</td></tr><tr><td>API</td><td><code>paper-api:1.21.8-R0.1-SNAPSHOT</code></td></tr><tr><td>Java</td><td><code>25</code></td></tr><tr><td>paper-plugin.yml api-version</td><td><code>1.21.8</code></td></tr><tr><td>构建方式</td><td>Maven 多模块聚合</td></tr></tbody></table><blockquote><p>插件仅面向 Minecraft 1.21.8 及以上版本开发，不兼容更低版本；<code>api-version</code> 声明为 <code>1.21.8</code>，低于该版本的服务器会被 Paper 拒绝加载。当前插件描述文件也声明了 Folia 支持。</p></blockquote><h2 id="模块定位" tabindex="-1">模块定位 <a class="header-anchor" href="#模块定位" aria-label="Permalink to &quot;模块定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>版本线</th><th>聚合</th><th>定位</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td><code>4.6.0</code></td><td>默认</td><td>公共基础库，所有业务模块都依赖它。</td></tr><tr><td>EmakiAttribute</td><td><code>4.6.0</code></td><td>默认</td><td>属性、资源、伤害、条件、PDC 属性 API。</td></tr><tr><td>EmakiForge</td><td><code>4.6.0</code></td><td>默认</td><td>锻造、图纸要求、材料贡献、品质和配方书。</td></tr><tr><td>EmakiStrengthen</td><td><code>4.6.0</code></td><td>默认</td><td>装备强化、星级阶段、保护、失败惩罚和刷新。</td></tr><tr><td>EmakiCooking</td><td><code>4.1.0</code></td><td>默认</td><td>世界工位式烹饪玩法。</td></tr><tr><td>EmakiLevel</td><td><code>1.4.0</code></td><td>默认</td><td>多等级类型、经验来源、升级需求、PDC、Placeholder 和 MythicMobs 经验 Drop。</td></tr><tr><td>EmakiCodex</td><td><code>1.0.0</code></td><td>默认</td><td>原版成就图鉴、成就页配置和 CoreLib 动作触发。</td></tr><tr><td>EmakiGem</td><td><code>2.6.0</code></td><td>private-modules</td><td>宝石、插槽、开孔、镶嵌、提取和升级。</td></tr><tr><td>EmakiSkills</td><td><code>2.6.0</code></td><td>private-modules</td><td>主动/被动技能、触发器、资源消耗、MythicMobs 桥接。</td></tr><tr><td>EmakiItem</td><td><code>2.6.0</code></td><td>private-modules</td><td>自定义物品、套装、触发器和自动更新。</td></tr><tr><td>EmakiStorage</td><td><code>1.0.0</code></td><td>private-modules</td><td>分页 GUI 仓库、单槽大额存量、容量档位与付费解锁。</td></tr></tbody></table><blockquote><p><code>private-modules</code> 是根 <code>pom.xml</code> 中定义的 profile，当根目录存在 <code>.key</code> 文件时自动激活，用于额外聚合 EmakiSkills、EmakiGem、EmakiItem 和 EmakiStorage。</p></blockquote><p>除上述服务器插件外，工程还包含各模块的 <code>emaki-*-api</code> 编译期构件。它们不是服务器插件，不要放进 <code>plugins/</code>。其中 <code>emaki-skills-api</code> 的 <code>emaki.jiuwu.craft.skills.api.pdc</code> 包持有装备技能 PDC 编解码契约，由 Item、Forge、Gem、Strengthen 在构建时嵌入并 relocate 到各自的运行时包名。</p><h2 id="为什么需要-corelib" tabindex="-1">为什么需要 CoreLib <a class="header-anchor" href="#为什么需要-corelib" aria-label="Permalink to &quot;为什么需要 CoreLib&quot;">​</a></h2><p>CoreLib 是 Emaki Series 的“基础设施层”。很多插件都会遇到相同问题，例如：</p><ul><li>如何在 YAML 中执行奖励、提示、扣费、命令、粒子、音效？</li><li>如何统一打开 GUI、处理按钮点击、保护交互状态？</li><li>如何识别 Vanilla、MMOItems、ItemsAdder、Nexo、Oraxen、EcoItems、CraftEngine 等来源的物品？</li><li>如何把不同模块写入的装备状态保存到 PDC，且不互相覆盖？</li><li>如何把锻造、强化、宝石、物品基础信息组合成最终展示？</li><li>如何写条件表达式、概率、延迟动作、经济扣费？</li></ul><p>如果每个模块都自己实现一套，最终会难以维护。CoreLib 把这些能力统一起来，业务模块只需要关注自己的玩法逻辑。</p><h2 id="常见组合方式" tabindex="-1">常见组合方式 <a class="header-anchor" href="#常见组合方式" aria-label="Permalink to &quot;常见组合方式&quot;">​</a></h2><h3 id="只做属性和战斗" tabindex="-1">只做属性和战斗 <a class="header-anchor" href="#只做属性和战斗" aria-label="Permalink to &quot;只做属性和战斗&quot;">​</a></h3><p>安装：</p><ol><li>EmakiCoreLib</li><li>EmakiAttribute</li><li>可选：PlaceholderAPI、MythicMobs、MMOItems</li></ol><p>适合：只想做 RPG 属性、伤害类型、资源状态、PAPI 展示和外部怪物技能联动。</p><h3 id="做装备成长" tabindex="-1">做装备成长 <a class="header-anchor" href="#做装备成长" aria-label="Permalink to &quot;做装备成长&quot;">​</a></h3><p>安装：</p><ol><li>EmakiCoreLib</li><li>EmakiAttribute</li><li>EmakiItem</li><li>EmakiForge</li><li>EmakiStrengthen</li><li>EmakiGem</li></ol><p>适合：做一条完整装备线，例如基础装备由 Item 生成，Forge 改造品质，Strengthen 提升星级，Gem 提供插槽与宝石属性，Attribute 负责最终数值计算。</p><h3 id="做等级成长" tabindex="-1">做等级成长 <a class="header-anchor" href="#做等级成长" aria-label="Permalink to &quot;做等级成长&quot;">​</a></h3><p>安装：</p><ol><li>EmakiCoreLib</li><li>EmakiLevel</li><li>可选：PlaceholderAPI、MythicMobs、EmakiAttribute、EmakiCooking、EmakiForge</li></ol><p>适合：制作主等级、战斗等级、采集等级、生活职业等级等多条成长线，并把经验来源接入原版事件、MythicMobs Drop 或其他 Emaki 插件的 Action。</p><h3 id="做技能系统" tabindex="-1">做技能系统 <a class="header-anchor" href="#做技能系统" aria-label="Permalink to &quot;做技能系统&quot;">​</a></h3><p>安装：</p><ol><li>EmakiCoreLib</li><li>EmakiSkills</li><li>MythicMobs</li><li>可选：EmakiAttribute、PlaceholderAPI、EmakiItem、EmakiLevel</li></ol><p>适合：让装备、权限、等级、配置或外部来源解锁技能，由 Skills 处理冷却、资源消耗和触发，再交给 MythicMobs 执行实际技能效果。</p><h3 id="做生活玩法" tabindex="-1">做生活玩法 <a class="header-anchor" href="#做生活玩法" aria-label="Permalink to &quot;做生活玩法&quot;">​</a></h3><p>安装：</p><ol><li>EmakiCoreLib</li><li>EmakiCooking</li><li>可选：EmakiLevel、CraftEngine、ItemsAdder、Nexo</li></ol><p>适合：制作砧板、炒锅、研磨机、蒸锅等世界工位，让玩家通过方块交互完成烹饪流程；如果需要厨艺/生活职业成长，可通过 EmakiLevel 或 CoreLib Action 给予经验。</p><h3 id="做成就图鉴" tabindex="-1">做成就图鉴 <a class="header-anchor" href="#做成就图鉴" aria-label="Permalink to &quot;做成就图鉴&quot;">​</a></h3><p>安装：</p><ol><li>EmakiCoreLib</li><li>EmakiCodex</li><li>可选：PacketEvents、PlaceholderAPI、MythicMobs</li></ol><p>适合：用 <code>advancements/*.yml</code> 把玩法目标做成原版成就页，由击杀、合成、钓鱼、破坏方块等 CoreLib 共享 gameplay 事件触发节点，并在节点完成时执行 CoreLib 动作发放奖励。安装 PacketEvents 时可额外注入成就树坐标。</p>',41)])])}const s=e(o,[["render",l]]);export{k as __pageData,s as default};
